const SNAKE_INFO={id:"beddomes-coral-snake",commonName:"Beddome's Coral Snake",scientificName:"Calliophis beddomei",namingAuthor:"Named after Colonel Richard Henry Beddome (1830–1911)",taxonomy:{kingdom:"Animalia",phylum:"Chordata",class:"Reptilia",order:"Squamata",family:"Elapidae",genus:"Calliophis",species:"C. beddomei"},endemicRegion:"Western Ghats Biodiversity Hotspot (South India)",iucnStatus:"Near Threatened (Habitat Loss & Fragmentation)",quickStats:[{label:"Scientific Name",value:"Calliophis beddomei",icon:"🐍"},{label:"Family",value:"Elapidae (Venomous)",icon:"🧪"},{label:"Endemic Hub",value:"Western Ghats",icon:"🏞️"},{label:"Habitat",value:"Leaf Litter & Humus",icon:"🍂"},{label:"Activity",value:"Nocturnal / Fossorial",icon:"🌙"},{label:"Conservation",value:"Near Threatened",icon:"🛡️"}]},ECOLOGICAL_PROFILE={overview:"Beddome's Coral Snake (Calliophis beddomei) is a small, highly secretive venomous snake endemic to the tropical wet evergreen and montane shola forests of the Southern Western Ghats.",distributionAndHabitat:"Restricted to wet evergreen forest floors and moist leaf litter layers at altitudes between 600m to 1,500m in Tamil Nadu (Nilgiris, Anamalai), Kerala (Wayanad, Agasthyamalai), and Karnataka.",behaviour:"Primarily nocturnal and fossorial (burrowing). When threatened, it coils its body tightly and displays its brilliant coral-pink underbelly as an aposematic warning signal while keeping its head hidden beneath coils.",diet:"Ophiophagous specialist feeding almost exclusively on small subterranean snakes (Uropeltids / shieldtail snakes, blind snakes Typhlopidae) and leaf-litter skinks.",reproduction:"Oviparous species; females lay small clutches of 2 to 4 elongated eggs under damp rotting logs or subterranean burrows during late monsoon.",threatsAndConservation:"Threatened by deforestation, cardamom and tea plantation expansion, leaf-litter clearing, forest fires, and road mortality across Western Ghat hill ranges.",ecologicalImportance:"Serves as an essential mid-trophic predator regulating fossorial reptile populations and functioning as a sensitive bioindicator of pristine forest soil moisture.",interestingFacts:["Features a striking ventral color pattern of bright coral-red to reddish-pink scales.","Possesses elongated venom glands extending far backward into the body cavity.","Named in honor of Richard Henry Beddome, former Chief Conservator of Forests in Madras Presidency who documented Indian herpetofauna.","Extremely docile and non-aggressive; bites to humans are virtually unrecorded due to its secretive leaf-burrowing habits."]},GALLERY_IMAGES=[{url:"https://upload.wikimedia.org/wikipedia/commons/thumb/1/1a/Calliophis_beddomei.jpg/800px-Calliophis_beddomei.jpg",caption:"Beddome's Coral Snake (Calliophis beddomei) exhibiting dorsal cylindrical body scales",category:"Specimen"},{url:"https://upload.wikimedia.org/wikipedia/commons/thumb/0/05/Western_Ghats_evergreen_forest.jpg/800px-Western_Ghats_evergreen_forest.jpg",caption:"Moist tropical evergreen forest floor of Western Ghats — Native habitat",category:"Habitat"}],REFERENCES=[{text:"IUCN Red List of Threatened Species — Calliophis beddomei Assessment.",link:"https://www.iucnredlist.org"},{text:"Smith, M. A. (1943). The Fauna of British India: Reptilia and Amphibia, Vol. III - Serpentes. Taylor & Francis, London.",link:"#"},{text:"Whitaker, Romulus & Captain, Ashok (2004). Snakes of India: The Field Guide. Draco Books.",link:"#"}];"undefined"!=typeof module&&module.exports&&(module.exports={SNAKE_INFO:SNAKE_INFO,ECOLOGICAL_PROFILE:ECOLOGICAL_PROFILE,GALLERY_IMAGES:GALLERY_IMAGES,REFERENCES:REFERENCES});